    def set_url(self, url: bytes) -> None:
        self.url = urlparse.urlsplit(url)
        self.set_line_attributes(url)

    def set_line_attributes(self, original_url: Optional[bytes] = None) -> None:
        if self.type == httpParserTypes.REQUEST_PARSER:
            if self.method == httpMethods.CONNECT and self.url:
                # When original_url is e.g. b'uni.corn:443', urlsplit treats
                # 'uni.corn' as scheme and '443' as path. Using self.url.path
                # (which would be just b'443') loses the host. Instead, use
                # the original URL with a '//' prefix so urlsplit correctly
                # identifies hostname and port from the netloc.
                if original_url is None:
                    original_url = urlparse.urlunsplit(self.url)
                u = urlparse.urlsplit(b'//' + original_url)
                self.host, self.port = u.hostname, u.port
            elif self.url:
                self.host, self.port = self.url.hostname, self.url.port \
